def to_cents(amount):
    return round(amount * 100)


def split_bill(total, people):
    """Split `total` into `people` shares that add up exactly. Earlier people pay the odd cents."""
    cents = to_cents(total)
    base, extra = divmod(cents, people)
    return [(base + (1 if i < extra else 0)) / 100 for i in range(people)]

from datetime import date


def _is_leap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def _birthday_in_year(month, day, year):
    # People born on Feb 29 celebrate on Feb 28 in non-leap years.
    if month == 2 and day == 29 and not _is_leap(year):
        day = 28
    return date(year, month, day)


def days_until(birthday, today):
    """Days from `today` until the next birthday (0 if it is today)."""
    this_year = _birthday_in_year(birthday.month, birthday.day, today.year)
    if this_year >= today:
        return (this_year - today).days
    next_year = _birthday_in_year(birthday.month, birthday.day, today.year + 1)
    return (next_year - today).days

def deep_merge(base, override):
    """Return a new dict: nested dicts are merged, other values from `override` win.
    Neither input is modified."""
    result = dict(base)
    for key, value in override.items():
        if (
            key in result
            and isinstance(result[key], dict)
            and isinstance(value, dict)
        ):
            result[key] = deep_merge(result[key], value)
        else:
            result[key] = value
    return result

def parse_env(text):
    """Parse KEY=VALUE lines. Blank lines and # comments are skipped; quotes around values are removed."""
    out = {}
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        key, value = line.split("=", 1)
        value = value.strip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in "\"'":
            value = value[1:-1]
        out[key.strip()] = value
    return out

FREE_SHIPPING_FROM = 50.00
STANDARD_FEE = 4.99
EXPRESS_SURCHARGE = 10.00


def shipping_fee(subtotal, express=False):
    """Standard fee unless the order qualifies for free shipping. Express adds a flat surcharge."""
    fee = 0.0 if subtotal >= FREE_SHIPPING_FROM else STANDARD_FEE
    if express:
        fee = fee + EXPRESS_SURCHARGE
    return round(fee, 2)

import functools


def memoize(fn):
    cache = {}

    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        key = (args, tuple(sorted(kwargs.items())))
        if key not in cache:
            cache[key] = fn(*args, **kwargs)
        return cache[key]

    wrapper.cache = cache
    return wrapper

class Note:
    def __init__(self, title, tags=[]):
        self.title = title
        self.tags = list(tags)

    def tag(self, label):
        if label not in self.tags:
            self.tags.append(label)
        return self

"""Split a list into fixed-size pages, numbered from 1."""


def page_count(items, size):
    if size <= 0:
        raise ValueError("size must be positive")
    return (len(items) + size - 1) // size


def get_page(items, number, size):
    """Return page `number` (1-based). Out-of-range pages are empty."""
    start = (number - 1) * size
    return items[start:start + size]

GRAMS_PER = {"g": 1, "kg": 1000, "oz": 28.3495, "lb": 453.592}


def to_grams(value, unit):
    try:
        return value * GRAMS_PER[unit]
    except KeyError:
        raise ValueError(f"unknown unit: {unit}") from None

def safe_int(value, default=0):
    """Parse an int from user input; return `default` for anything that is not a whole number."""
    try:
        return int(value)
    except (TypeError, ValueError):
        return default

import re

VERSION_RE = re.compile(r"v?(\d+)\.(\d+)\.(\d+)(?:-[0-9A-Za-z.]+)?")


def parse_version(text):
    """'v1.2.3' or '1.2.3-beta' -> (1, 2, 3). Anything else raises ValueError."""
    m = VERSION_RE.fullmatch(text.strip())
    if not m:
        raise ValueError(f"not a version: {text!r}")
    return tuple(int(g) for g in m.groups())


def is_newer(a, b):
    return parse_version(a) > parse_version(b)

import re


def slugify(title):
    """'  Hello, World!  ' -> 'hello-world'"""
    slug = re.sub(r"[^a-z0-9]+", "-", title.lower())
    return slug.strip("-")

def mean(xs):
    if not xs:
        raise ValueError("mean() arg is an empty sequence")
    return sum(xs) / len(xs)


def median(xs):
    if not xs:
        raise ValueError("median() arg is an empty sequence")
    s = sorted(xs)
    mid = len(s) // 2
    if len(s) % 2:
        return s[mid]
    return (s[mid - 1] + s[mid]) / 2

def depth(node):
    """Number of levels in a tree of {"value": ..., "children": [...]} dicts. Empty tree (None) is 0."""
    if node is None:
        return 0
    if not node["children"]:
        return 1
    return 1 + max(depth(child) for child in node["children"])


def count_nodes(node):
    if node is None:
        return 0
    return 1 + sum(count_nodes(c) for c in node["children"])
